package injectcheck

import "github.com/cilium/ebpf/asm"

// Helper argument counts from the Linux helper prototypes generated by libbpf in bpf_helper_defs.h.
// Unknown IDs conservatively use all five arguments. These ABI facts are
// independent of the transformer's site classification and liveness claims.
func helperReads(id int64) uint16 {
	if id < 0 || int64(asm.BuiltinFunc(id)) != id {
		return argRegs
	}
	switch asm.BuiltinFunc(id) {
	case asm.FnKtimeGetNs, asm.FnGetPrandomU32, asm.FnGetSmpProcessorId, asm.FnGetCurrentPidTgid, asm.FnGetCurrentUidGid, asm.FnGetCurrentTask, asm.FnGetNumaNodeId, asm.FnGetCurrentCgroupId, asm.FnJiffies64, asm.FnKtimeGetBootNs, asm.FnGetCurrentTaskBtf, asm.FnKtimeGetCoarseNs, asm.FnGetRetval, asm.FnKtimeGetTaiNs:
		return 0
	case asm.FnGetCgroupClassid, asm.FnSkbVlanPop, asm.FnGetRouteRealm, asm.FnGetHashRecalc, asm.FnSetHashInvalid, asm.FnGetSocketCookie, asm.FnGetSocketUid, asm.FnRcRepeat, asm.FnSkbCgroupId, asm.FnSkRelease, asm.FnSpinLock, asm.FnSpinUnlock, asm.FnSkFullsock, asm.FnTcpSock, asm.FnSkbEcnSetCe, asm.FnGetListenerSock, asm.FnSendSignal, asm.FnSendSignalThread, asm.FnGetNetnsCookie, asm.FnGetCurrentAncestorCgroupId, asm.FnSkCgroupId, asm.FnSkcToTcp6Sock, asm.FnSkcToTcpSock, asm.FnSkcToTcpTimewaitSock, asm.FnSkcToTcpRequestSock, asm.FnSkcToUdp6Sock, asm.FnSkbCgroupClassid, asm.FnThisCpuPtr, asm.FnSockFromFile, asm.FnSysClose, asm.FnTimerCancel, asm.FnGetFuncIp, asm.FnGetAttachCookie, asm.FnTaskPtRegs, asm.FnSkcToUnixSock, asm.FnGetFuncArgCnt, asm.FnSetRetval, asm.FnXdpGetBuffLen, asm.FnSkcToMptcpSock:
		return 1 << asm.R1
	case asm.FnMapLookupElem, asm.FnMapDeleteElem, asm.FnGetCurrentComm, asm.FnPerfEventRead, asm.FnRedirect, asm.FnSkbChangeType, asm.FnCurrentTaskUnderCgroup, asm.FnSkbPullData, asm.FnCsumUpdate, asm.FnXdpAdjustHead, asm.FnSetHash, asm.FnXdpAdjustMeta, asm.FnOverrideReturn, asm.FnSockOpsCbFlagsSet, asm.FnMsgApplyBytes, asm.FnMsgCorkBytes, asm.FnXdpAdjustTail, asm.FnGetLocalStorage, asm.FnSkbAncestorCgroupId, asm.FnMapPopElem, asm.FnMapPeekElem, asm.FnSkStorageDelete, asm.FnTcpSendAck, asm.FnSkAncestorCgroupId, asm.FnRingbufSubmit, asm.FnRingbufDiscard, asm.FnRingbufQuery, asm.FnCsumLevel, asm.FnInodeStorageDelete, asm.FnPerCpuPtr, asm.FnRedirectPeer, asm.FnTaskStorageDelete, asm.FnBprmOptsSet, asm.FnTimerSetCallback, asm.FnGetFuncRet, asm.FnKptrXchg, asm.FnRingbufSubmitDynptr, asm.FnRingbufDiscardDynptr, asm.FnTcpRawCheckSyncookieIpv4, asm.FnTcpRawCheckSyncookieIpv6, asm.FnCgrpStorageDelete:
		return 1<<asm.R1 | 1<<asm.R2
	case asm.FnProbeRead, asm.FnTailCall, asm.FnCloneRedirect, asm.FnSkbVlanPush, asm.FnGetStackid, asm.FnSkbGetTunnelOpt, asm.FnSkbSetTunnelOpt, asm.FnSkbChangeProto, asm.FnSkbUnderCgroup, asm.FnProbeWriteUser, asm.FnSkbChangeTail, asm.FnSkbChangeHead, asm.FnProbeReadStr, asm.FnRedirectMap, asm.FnPerfProgReadValue, asm.FnBind, asm.FnLwtSeg6AdjustSrh, asm.FnMapPushElem, asm.FnRcPointerRel, asm.FnSysctlGetCurrentValue, asm.FnSysctlGetNewValue, asm.FnSysctlSetNewValue, asm.FnProbeReadUser, asm.FnProbeReadKernel, asm.FnProbeReadUserStr, asm.FnProbeReadKernelStr, asm.FnSkAssign, asm.FnSeqWrite, asm.FnRingbufReserve, asm.FnReserveHdrOpt, asm.FnDPath, asm.FnCopyFromUser, asm.FnImaInodeHash, asm.FnSysBpf, asm.FnTimerInit, asm.FnTimerStart, asm.FnGetBranchSnapshot, asm.FnStrncmp, asm.FnGetFuncArg, asm.FnSkbSetTstamp, asm.FnImaFileHash, asm.FnMapLookupPercpuElem, asm.FnDynptrData, asm.FnTcpRawGenSyncookieIpv4, asm.FnTcpRawGenSyncookieIpv6:
		return 1<<asm.R1 | 1<<asm.R2 | 1<<asm.R3
	case asm.FnMapUpdateElem, asm.FnSkbGetTunnelKey, asm.FnSkbSetTunnelKey, asm.FnSkbLoadBytes, asm.FnSkbAdjustRoom, asm.FnSkRedirectMap, asm.FnSockMapUpdate, asm.FnPerfEventReadValue, asm.FnMsgRedirectMap, asm.FnMsgPullData, asm.FnGetStack, asm.FnFibLookup, asm.FnSockHashUpdate, asm.FnMsgRedirectHash, asm.FnSkRedirectHash, asm.FnLwtPushEncap, asm.FnLwtSeg6StoreBytes, asm.FnLwtSeg6Action, asm.FnRcKeydown, asm.FnSkSelectReuseport, asm.FnMsgPushData, asm.FnMsgPopData, asm.FnSysctlGetName, asm.FnStrtol, asm.FnStrtoul, asm.FnSkStorageGet, asm.FnReadBranchRecords, asm.FnGetNsCurrentPidTgid, asm.FnRingbufOutput, asm.FnGetTaskStack, asm.FnLoadHdrOpt, asm.FnStoreHdrOpt, asm.FnInodeStorageGet, asm.FnSeqPrintfBtf, asm.FnRedirectNeigh, asm.FnTaskStorageGet, asm.FnForEachMapElem, asm.FnBtfFindByNameKind, asm.FnTraceVprintk, asm.FnKallsymsLookupName, asm.FnLoop, asm.FnXdpLoadBytes, asm.FnXdpStoreBytes, asm.FnDynptrFromMem, asm.FnRingbufReserveDynptr, asm.FnUserRingbufDrain, asm.FnCgrpStorageGet:
		return 1<<asm.R1 | 1<<asm.R2 | 1<<asm.R3 | 1<<asm.R4
	default:
		return argRegs
	}
}
